// Original educational recipes. Numeric settings are starting points, not measured Serum presets.
const PATCHES=[];
function patch(id,name,family,level,styles,description,config){PATCHES.push({id,name,family,level,styles,description,engine:config.wave==='noise'?'Noise':'Wavetable',wave:'sawtooth',voices:1,detune:0,note:36,pattern:'rolling',amp:[2,0,220,0,50],filter:'MG Low 24',cut:220,peak:1800,res:15,env:180,fx:'Leave the FX rack empty while learning the core sound.',movement:'Keep modulation off apart from the envelope described above. Make the rhythm with MIDI notes.',macro:['Tone','Filter 1 Cutoff: keep the low end at the recipe setting; raise the high end by one octave.'],source:'OSC A: Analog → Basic Shapes; select the saw shape with WT POS. LEVEL 65%.',why:'The envelope makes a bright beginning and a darker tail. That changing brightness makes each note feel played.',hear:'A clear attack followed by a darker, shorter body; gaps stay audible.',fix:'If it stays bright, confirm OSC A routes to Filter 1 and that the filter is on. If it is silent, temporarily open the cutoff.',variants:['Halve ENV 2 decay for a tighter answer.','Raise the cutoff one octave for a brighter version.'],challenge:'Rebuild the amplitude and filter envelopes without reading the numbers.',mix:'Play it with your kick. Shorten the release if the next kick loses definition.',...config});}

patch('round-sub','Round sub','Bass',1,'Deep house · minimal · techno','The foundation: a low, clean note that stops exactly when you need it to.',{wave:'sine',filter:'Off',cut:18000,peak:18000,amp:[4,0,200,100,65],note:33,pattern:'offbeat',source:'OSC A: Analog → Basic Shapes; WT POS on the sine (one smooth wave). LEVEL 65%; UNISON 1. Leave OCT at 0; the MIDI note provides the low register.',why:'A sine has no upper harmonics. The note length and release define the groove more than a filter does.',hear:'A soft, steady low note with no buzz or click. Laptop speakers may barely reproduce it.',fix:'Clicks: raise ATK to 6 ms and REL to 80 ms. Too weak on small speakers: try the Warm sub recipe; a filter cannot add missing harmonics.',macro:['Length','ENV 1 REL: 30 → 120 ms. Keep notes short enough to leave space.'],variants:['Change sine to triangle for quiet upper harmonics.','Lower SUS to 0% and use DEC 300 ms for a falling pulse.'],mix:'Use one sub layer at a time. Audition MIDI 29–41 (about 44–87 Hz) against the kick; lower is not automatically heavier.'});
patch('warm-sub','Warm sub','Bass',1,'House · dub techno','A small amount of buzz makes a sub readable on smaller speakers.',{wave:'triangle',filter:'MG Low 12',cut:650,peak:650,env:0,amp:[4,0,350,65,70],note:33,pattern:'offbeat',source:'OSC A: Basic Shapes → triangle. LEVEL 60%; UNISON 1. Route A to Filter 1.',fx:'Add Distortion → Soft Clip after the filter. Start DRIVE 15%, MIX 25%; lower the output to match the bypassed loudness.',why:'Triangle harmonics and gentle clipping make the pitch easier to hear without needing another bass oscillator.',hear:'A rounded low note with a small, audible middle; the pitch stays stable.',fix:'Fuzz dominates: reduce distortion mix first, then drive. Do not compensate with a huge sub boost.',variants:['Remove distortion and compare the pitch on quiet speakers.','Swap triangle for sine and increase drive gradually.']});
patch('rolling-bass','Rolling techno bass','Bass',1,'Rolling techno · hardgroove · deep tech','Short, dark pulses that lock between the kick drums.',{amp:[2,0,175,0,35],cut:180,peak:1400,env:110,note:33,source:'OSC A: Basic Shapes → saw. LEVEL 60%; UNISON 1; RAND 0% for a repeatable start. Try PHASE 90° if the attack clicks.',movement:'No LFO needed. Program short sixteenth notes with gaps. Set MIDI velocities to 95 / 65 / 80 for a repeating accent idea; add VELO → Filter 1 Cutoff, a small positive amount, only after the basic patch works.',why:'The filter closes before the volume ends. You hear a bite, then a dark body, then room for the next event.',hear:'A small “dug” on each note, with silence between hits. It should still groove without effects.',fix:'A continuous drone means SUS or release is too high, or notes overlap. A sharp click needs 3–5 ms attack, not more reverb.',variants:['DEC 260 ms and ENV 2 DEC 180 ms: a lazier deep-tech roll.','Change saw to square and reduce resonance to 5%: a hollow jack.'],challenge:'Build it from Init in five minutes. Explain why turning ENV 1 SUS up destroys the gaps.'});
patch('offbeat-bass','Offbeat house bass','Bass',1,'Classic house · progressive house','A buoyant bass note on each “and” between the kicks.',{wave:'square',pattern:'offbeat',cut:260,peak:1900,env:170,amp:[3,0,260,15,45],note:33,source:'OSC A: Basic Shapes → square. LEVEL 55%; UNISON 1. Route A to Filter 1.',movement:'Place four eighth notes halfway between quarter-note kicks. Keep their lengths below half a beat. Try VELO → Cutoff so one offbeat can answer another.',why:'The silence before the note makes the bounce. The filter envelope gives a square wave a rounder front.',hear:'A hollow “bup” after each kick, with no continuous high buzz.',variants:['Change to saw for a denser, more modern bass.','ENV 1 SUS 0% and DEC 150 ms: a more clipped minimal-house version.']});
patch('rubber-bass','Rubber FM bass','Bass',2,'Tech house · minimal house','A springy, vowel-like “donk” that settles into a rounded note.',{wave:'sine',fm:1.4,ratio:2,cut:500,peak:3800,env:160,amp:[2,0,250,0,50],pattern:'syncopated',source:'OSC A: Basic Shapes → sine, LEVEL 65%. Enable OSC B: sine, OCT +1, LEVEL 0%. B must remain powered on. On A choose WARP → FM (B), start at 12%.',movement:'ENV 3: ATK 0 ms, HOLD 0, DEC 120 ms, SUS minimum, REL 30 ms. Drag ENV 3 to A WARP amount: unipolar upward, roughly 12% → 30% at the attack. B is the modulator; it need not be audible.',why:'An oscillator moving another oscillator at audio speed adds harmonics. A fast envelope removes those harmonics as the note settles.',hear:'A rounded “yow” front, not a separate high sine from B.',fix:'Only a sine: check B power and A’s FM (B) selection. A shriek: lower A Warp amount before closing the filter.',macro:['Bite','A WARP FM (B): 8% → 28%. Check the loudest end and lower output if needed.'],variants:['B OCT 0: more hollow; B OCT +2: more metallic.','ENV 3 DEC 60 ms: shorter, woodier attack.']});
patch('reese','Dark Reese','Bass',2,'Raw techno · breaks · warehouse','Slow beating between two detuned saws; a moving middle above your low foundation.',{voices:2,detune:9,amp:[12,0,400,85,120],cut:1100,peak:1100,env:0,pattern:'long',source:'OSC A and OSC B: Basic Shapes → saw; UNISON 1 each; LEVEL 40% each. A FIN −7 cents, B FIN +7 cents. Route both to Filter 1. SUB off.',movement:'LFO 1: triangle, BPM on, RATE 2 bars, FREE. Route to Filter 1 Cutoff for a gentle 700–1600 Hz sweep. Use unipolar modulation from 700 Hz; do not sweep down into silence.',why:'Slightly different pitches beat against each other. The motion is inside the source, so it survives with all FX bypassed.',hear:'A slow, restless buzz with a moving centre. The very lowest energy may fluctuate.',fix:'Weak in mono: reduce detune, centre both pans and check without chorus. For a reliable sub, high-pass this layer in the DAW and add a separate mono sine.',macro:['Motion','B FIN: +3 → +12 cents; leave A FIN at −7 cents.'],variants:['Cutoff 450 Hz: distant, woolly bass.','OCT +1 on both oscillators: a mid-bass answer above a separate sub.'],mix:'Treat a wide Reese as a middle layer. Check the full bass in mono; detuned oscillators can cancel even without stereo effects.'});
patch('acid-house','Acid house line','Bass',2,'Acid house · Chicago','A resonant squelch whose accents and slides are part of the instrument.',{filter:'Acid Ladder',res:55,cut:220,peak:2600,env:190,amp:[1,0,300,35,40],note:36,pattern:'acid',source:'OSC A: Basic Shapes → saw; LEVEL 55%; UNISON 1. Filter 1: choose Acid Ladder. This is a 303-inspired study, not an exact 303 circuit or sequencer reproduction.',movement:'Enable MONO and LEGATO in voicing. Set PORTA to about 80 ms and enable its legato-only option. Overlap only the notes you want to slide. Add VELO → Filter 1 Cutoff, a small positive amount; use high velocity on selected accents.',why:'Resonance highlights the moving cutoff. Pitch slides connect notes while velocity changes how hard the filter opens.',hear:'“Ow” accents and a few connected slides; most notes remain distinct.',fix:'Every note slides: check the legato-only portamento option and shorten the non-slide notes. No envelope on overlapped notes can be expected with legato; leave gaps for fresh attacks.',macro:['Open','Filter 1 Cutoff: 180 → 1800 Hz. Keep the ENV 2 opening above that base modest at the high end.'],variants:['Square wave: hollower, more nasal acid.','ENV 2 DEC 80 ms: tiny rubber accents.'],mix:'Resonance can change both loudness and perceived bass. Match level while sweeping and check the line with the kick.'});
patch('acid-techno','Driven acid techno','Bass',2,'Acid techno · peak time','The acid recipe pushed through a rougher, more forward middle.',{filter:'Acid Ladder',res:65,cut:340,peak:3800,env:130,amp:[1,0,210,0,35],pattern:'acid',source:'OSC A: Basic Shapes → saw; LEVEL 45%; UNISON 1. Filter 1: Acid Ladder. Keep SUB off while finding the drive.',fx:'After Filter 1, add Distortion → Tube. Start DRIVE 30%, MIX 40%. Add an EQ high shelf cut only if the top becomes abrasive; reduce drive before relying on EQ.',movement:'MONO on; start LEGATO off to hear every filter attack. Later enable legato-only PORTA at 60 ms and overlap two notes. Automate cutoff slowly over eight bars in your DAW.',why:'Distortion after a resonant filter reshapes its moving peak. The sweep remains the identity; gain supplies the aggression.',hear:'A sharper bark than the house version, with the note still identifiable.',fix:'Fizzy wall: halve DRIVE and lower ENV 2 peak. Bass vanishes: reduce resonance and compare at the same loudness.',variants:['Move distortion before a filter in the FX rack to hear a smoother result.','Square source and 30% resonance: less screaming, more groove.']});
patch('wobble','Talking bass wobble','Bass',2,'Bass house · UK-influenced house','A held bass note articulated by a repeating filter movement.',{wave:'square',cut:250,peak:250,env:0,amp:[4,0,250,100,70],pattern:'long',wobble:2,source:'OSC A: Basic Shapes → square. LEVEL 55%; UNISON 1. Filter 1: MG Low 24, RES 30%.',res:30,movement:'LFO 1: draw a triangle, BPM on, RATE 1/8, RETRIG on. Assign to Filter 1 Cutoff, unipolar upward: base 250 Hz, top about 2200 Hz. Hold one note to hear two openings per beat.',why:'The note stays held while a repeating modulation creates new syllables. ENV 2 is unnecessary here.',hear:'A regular “wah-wah” during one held MIDI note.',fix:'One wah only: LFO is in ENVELOPE mode. Erratic starts: choose RETRIG. Too busy: change rate to 1/4.',macro:['Talk','LFO 1 modulation depth to Filter 1 Cutoff: about 1 → 3 octaves. Use Matrix Aux Macro 1 for depth control.'],variants:['Rate 1/4: a slower head nod.','Draw a falling ramp instead of triangle: repeated plucks within one note.']});
patch('ebm','EBM octave bass','Bass',2,'Industrial · EBM · dark techno','A hard, mechanical bass with a bright octave in the attack.',{wave:'sawtooth',ratio:2,fm:.3,cut:380,peak:2500,env:80,amp:[1,0,150,0,25],pattern:'octaves',source:'OSC A: saw, LEVEL 50%. OSC B: square, OCT +1, LEVEL 18%. UNISON 1 on both; route both to Filter 1.',fx:'Distortion → Soft Clip, DRIVE 25%, MIX 40%. No reverb on the main bass.',movement:'Use alternating root and octave MIDI notes. ENV 2 decay stays shorter than ENV 1 decay. Keep phase randomization low for repeatable hits.',why:'The octave layer and clipped envelope make a rigid, bright front. The short decay leaves room for a fast rhythm.',hear:'A terse, barking sequence with a clear low root.',variants:['Mute B: drier and more minimal.','B SEM +7 instead of OCT +1: a clangorous fifth; use sparingly in a busy mix.']});

patch('deep-stab','Deep house chord stab','Chords',1,'Deep house · garage','A soft-edged minor seventh chord with a short, warm tail.',{note:57,pattern:'chords',amp:[5,0,480,0,120],cut:900,peak:4600,env:260,filter:'MG Low 12',source:'OSC A: Basic Shapes → saw; LEVEL 45%; UNISON 1. MONO off; set polyphony to at least 8. Play A–C–E–G as four MIDI notes (57, 60, 64, 67); do not tune oscillators to a chord as well.',fx:'Chorus MIX 12%, then Reverb MIX 12%, DECAY about 1.2 s. Keep the dry chord clearly louder than its tail.',why:'The MIDI voicing supplies the harmony; the filter envelope supplies the soft “chuh” articulation.',hear:'Four pitches arrive together, then darken as they fade.',fix:'Only one note sounds: turn MONO off. Too thick: remove the lowest chord note or move the whole voicing up an octave.',variants:['Use MIDI 57, 60, 64, 71 for a minor add9 colour.','DEC 220 ms and reverb off: tighter garage chop.'],mix:'Keep the bass root on its own track. Chord roots need not sit in the sub register.'});
patch('dub-stab','Dub techno chord','Chords',2,'Dub techno · deep techno','A dark chord whose filtered echoes become the rhythm.',{note:57,pattern:'sparse-chords',amp:[3,0,230,0,80],cut:650,peak:2700,env:130,filter:'MG Low 12',space:.42,source:'OSC A: saw, LEVEL 45%, UNISON 1. Polyphony 8+. Play MIDI 57, 60, 64, 67 together. Route A to Filter 1.',fx:'Delay: BPM sync, dotted 1/8, FEEDBACK 35%, MIX 25%; darken its repeats with its filter controls. Reverb after Delay: DECAY 2.5 s, MIX 15%. Start with all bus sends at zero.',movement:'Macro 1 moves Filter 1 Cutoff 450 → 2200 Hz. For one “throw”, briefly raise delay MIX to 40% on the last chord, then return to 25%. Leave FEEDBACK below 55% while learning.',why:'Space between dry hits lets the echoes form a second pattern. Filtering the repeats separates them from the next chord.',hear:'A short chord, then quieter, darker replies that die away.',fix:'Endless wash: reduce feedback first, then reverb decay. Dry chord too long: reduce ENV 1 decay before reducing delay.',variants:['Delay straight 1/4: a more spacious pulse.','Change the chord to 57, 60, 67: an open minor voicing.'],mix:'Keep the wet low end out of the kick’s way. Listen to eight bars so you judge the accumulated echoes, not only the first hit.'});
patch('rave-stab','Rave chord stab','Chords',2,'Rave techno · warehouse house','A bright, blunt chord hit made with oscillator intervals.',{note:57,pattern:'stab',amp:[1,0,200,0,65],cut:2300,peak:7000,env:100,voices:3,detune:5,stack:[0,3,7],source:'OSC A, B and C: Basic Shapes → saw, LEVEL 30% each, UNISON 1. A SEM 0, B SEM +3, C SEM +7. Route all three to Filter 1. Play single MIDI notes; the oscillators already make a minor triad.',fx:'Distortion → Soft Clip, DRIVE 15%, MIX 30%. Optional Reverb MIX 8%, DECAY 0.8 s.',why:'Fixed oscillator intervals turn one key into a minor chord. Transposing that whole shape creates the parallel-chord rave sound.',hear:'A solid minor triad on a single key; a sharp start with a short tail.',fix:'Too many notes: use single MIDI notes, not the four-note chord pattern from Deep house stab. Fixed minor shapes will not follow every chord progression diatonically.',variants:['B SEM +4: major instead of minor.','B SEM +7, C SEM +12: an open fifth/octave stack.']});
patch('organ','House organ','Chords',1,'90s house · garage','A hollow, steady organ made by adding sine-wave harmonics.',{wave:'sine',note:57,pattern:'chords',amp:[2,0,180,85,55],filter:'Off',cut:18000,peak:18000,stack:[0,12,19],source:'A, B and C: Basic Shapes → sine, UNISON 1. A LEVEL 50%, OCT 0; B LEVEL 25%, OCT +1; C LEVEL 15%, OCT +1 and SEM +7 (19 semitones above A). All route Main. MONO off; polyphony 8+.',fx:'Optional Chorus MIX 10%. Keep Reverb MIX below 10%, DECAY about 0.7 s.',why:'The second and approximately third harmonics act like organ drawbars. There is no hammer decay while you hold a note.',hear:'A hollow sustained note that cuts off quickly when released. This is a synthesized organ, not the sampled M1 organ.',fix:'Sounds like a separate high whistle: lower C. Sounds like a pluck: raise ENV 1 SUS to 85%.',macro:['Drawbar','OSC C LEVEL: 0% → 25%.'],variants:['Mute C and raise B: rounder and simpler.','ENV 1 DEC 180 ms, SUS 0%: organ bass; play MIDI 36–48.']});
patch('piano','Piano house keys','Chords',1,'Piano house · soulful house','Start with a piano multisample, then shape it to leave room for the groove.',{engine:'Multisample',note:60,pattern:'chords',amp:[1,0,1300,50,170],cut:9000,peak:9000,env:0,filter:'MG Low 12',source:'OSC A header → Multisample. Open the content selector → Factory → Keys; choose an acoustic piano by auditioning the installed choices. LEVEL 55%, UNISON 1, pitch tracking on. MONO off, polyphony at least 12. Content names vary by library version.',fx:'Reverb MIX 10%, DECAY 1 s. Avoid large chorus until the dry piano rhythm works.',movement:'Play chord hits with different MIDI velocities. Audition 50 versus 110: the multisample may change timbre as well as level. Use short MIDI gates to keep the hook percussive.',why:'A real piano attack contains many interacting partials. Multisamples supply that complexity; envelopes and performance place it in the track.',hear:'A recognisable hammer attack and a ringing tail. This guide does not provide the source piano audio.',fix:'Sound stops unnaturally: increase REL slightly. Mud: move the voicing up and reduce release before EQ.',macro:['Shade','Filter 1 Cutoff: 2500 → 12000 Hz.'],variants:['Choose an electric piano from Keys for a softer reply.','Shorten DEC to 450 ms and SUS to 0% for a clipped house stab.']});
patch('fm-keys','Glass electric keys','Chords',2,'Deep house · lo-fi house','A bell-like attack that softens into a simple, musical body.',{wave:'sine',fm:1.1,ratio:3,note:60,pattern:'chords',amp:[3,0,1200,12,260],cut:6000,peak:6000,env:0,source:'A: sine LEVEL 55%. B: sine, OCT +1 and SEM +7 (about 3:1), LEVEL 0%, power on. A WARP → FM (B), amount 8%. Polyphony 12+.',movement:'ENV 3: ATK 0, HOLD 0, DEC 240 ms, SUS minimum, REL 80 ms. Route upward to A WARP for about 8% → 22% on attack. Add a small positive VELO → A WARP assignment so harder notes brighten.',fx:'Chorus MIX 8%, then Reverb MIX 12%, DECAY 1.4 s.',why:'A near-integer frequency ratio gives a pitched bell colour. The modulation decays faster than the note, like the hard strike on a tine.',hear:'A little “ting” followed by a softer, rounded sustain.',fix:'Clangy and dissonant: lower Warp amount or set B OCT +1, SEM 0 for an exact 2:1 ratio.',variants:['B OCT +2, SEM 0: brighter, higher partials.','ENV 3 DEC 80 ms: a tiny mallet front.']});
patch('disco-brass','Disco synth brass','Chords',2,'Disco house · classic house','A short upward bloom before the chord barks and settles.',{note:57,pattern:'chords',amp:[18,0,420,45,110],cut:650,peak:4300,env:280,envAttack:35,envSustain:25,envRelease:90,voices:2,detune:5,source:'OSC A: saw, UNISON 2, DETUNE 0.05, LEVEL 45%. MONO off, polyphony 12+. Route A to Filter 1.',movement:'ENV 2 ATK 35 ms gives the brass “bwah”; HOLD 0, DEC 280 ms, SUS 25%, REL 90 ms. Set upward cutoff movement from 650 Hz to roughly 4300 Hz. Play staccato minor seventh or major sixth chords.',why:'A brief filter opening after the note starts imitates the way a brass section swells into its attack.',hear:'A little bloom rather than an instant pluck. The held chord still has a body.',fix:'Sounds like a pad: reduce both attack times. Sounds too plucky: raise ENV 2 sustain slightly.',variants:['ATK 70 ms: softer, funkier swell.','UNISON 1: focused old-school brass.']});
patch('chord-memory','One-key minor ninth','Chords',2,'Deep techno · microhouse','A compact, floating chord texture from three deliberately chosen intervals.',{note:57,pattern:'stab',amp:[8,0,650,0,190],cut:1100,peak:4000,env:300,stack:[0,3,14],source:'A, B and C: triangle, LEVEL 35% each, UNISON 1. A SEM 0; B SEM +3; C OCT +1, SEM +2 (+14 total). Route all to Filter 1. Play one MIDI note at a time. The root, minor third and ninth omit the fifth.',wave:'triangle',fx:'Delay straight 1/8, FEEDBACK 22%, MIX 15%. Reverb MIX 10%, DECAY 1.5 s.',why:'Leaving out the fifth makes the shape less dense. The high ninth supplies colour while the root and third define minor.',hear:'A soft, slightly unresolved chord from a single key.',fix:'Clashing with a progression: check the actual pitches after transposing. A fixed shape does not know the key of your song.',variants:['C +10 semitones: root/third/minor seventh.','B +4 and C +14: a major add9 colour.']});

patch('melodic-pluck','Melodic techno pluck','Leads',1,'Melodic techno · progressive house','The essential bright-to-dark pluck that carries a repeating motif.',{note:57,pattern:'melody',amp:[2,0,480,0,100],cut:650,peak:6500,env:230,voices:3,detune:7,source:'OSC A: Basic Shapes → saw, UNISON 3, DETUNE 0.08, LEVEL 45%. MONO off; polyphony 8+. Filter 1: MG Low 24.',fx:'Delay dotted 1/8, FEEDBACK 25%, MIX 18%. Reverb MIX 12%, DECAY 1.8 s. Get the dry pluck working first.',why:'A large filter sweep gives an expressive attack. The dark tail leaves room for the next note without losing the note’s pitch.',hear:'A definite “tah” that softens; delay answers rather than masking the next note.',variants:['ENV 2 DEC 90 ms: a small, glassy tick.','ENV 2 DEC 500 ms: an opening, more emotional phrase.'],mix:'Use the MIDI from a Fieldwork V3 melody here. If every note feels too busy, shorten the patch before rewriting the motif.'});
patch('hypnotic-bleep','Hypnotic bleep','Leads',1,'Minimal techno · bleep · hypnotic','A narrow, repetitive tone whose small changes stay audible.',{wave:'triangle',note:69,pattern:'hypnotic',amp:[2,0,120,0,35],filter:'MG Low 12',cut:1200,peak:4000,env:70,res:25,source:'OSC A: Basic Shapes → triangle, LEVEL 60%; UNISON 1. Filter 1 on. Polyphony 4 is enough for short tails.',movement:'Use only three MIDI pitches: A, C and E. Keep the first five notes identical, then change the last. Map a macro to cutoff so you can make one small change per four bars.',why:'A sparse source and short envelope make rhythm and subtle tone changes easy to hear.',hear:'A small “pip”, not a huge lead. The repetition should be hypnotic at low volume.',variants:['Sine instead of triangle: purer bleeps.','Add delay MIX 20%, time 3/16, feedback 30% for interlocking replies.']});
patch('supersaw','Open supersaw lead','Leads',2,'Melodic house · trance techno','A wide saw stack with a clear central pitch and room to open.',{note:57,pattern:'melody',amp:[8,0,650,70,160],cut:1500,peak:6500,env:350,voices:7,detune:15,source:'OSC A: saw, UNISON 7, DETUNE 0.14, BLEND about 65%, LEVEL 40%. Leave other oscillators off. MONO off; polyphony 8+.',fx:'Reverb MIX 15%, DECAY 2 s. Delay straight 1/4, feedback 20%, MIX 12%. Avoid stacking extra widening before checking mono.',movement:'Macro 1 opens Filter 1 Cutoff 1500 → 10000 Hz. Make a held note work first, then use a melody with longer notes than the pluck recipe.',why:'Several detuned voices spread the same pitch. Too much detune makes the pitch centre vague; more voices is not always better.',hear:'A broad, stable pitch with shimmer at the sides, even at moderate level.',fix:'Seasick: lower DETUNE to 0.08. CPU spikes: reduce UNISON to 4 before adding more layers.',variants:['UNISON 3, DETUNE 0.06: intimate progressive lead.','SUS 0%, DEC 250 ms: a wide rave pluck.']});
patch('portamento-lead','Singing glide lead','Leads',2,'Progressive · melodic techno','A focused, vocal-like mono line with intentional connections.',{wave:'square',note:60,pattern:'glide',amp:[8,0,450,75,90],cut:900,peak:3300,env:300,source:'OSC A: square, LEVEL 55%, UNISON 1. MONO on; LEGATO on. PORTA about 100 ms; enable legato-only portamento.',movement:'Make a four-note phrase. Leave the first note separate, then overlap notes two and three by a sixteenth. The overlap creates the slide; ordinary separated notes should jump cleanly.',fx:'Delay straight 1/8, FEEDBACK 20%, MIX 15%. Reverb MIX 10%, DECAY 1.3 s.',why:'Legato preserves continuity across overlapping notes. The musical connection comes from MIDI length as well as the synth setting.',hear:'One clean attack followed by a smooth pitch transition only where notes overlap.',fix:'No slide: verify MONO, PORTA time and actual note overlap. Every note smears: shorten your gates.',variants:['Saw source: brighter, more urgent.','PORTA 35 ms: a subtle glide rather than a big slide.']});
patch('fm-bell','FM bell sequence','Leads',2,'Minimal · melodic techno · afro house','A bright pitched strike with a long, fading ring.',{wave:'sine',fm:2.1,ratio:3.01,note:69,pattern:'melody',amp:[1,0,1700,0,380],cut:9000,peak:9000,env:0,source:'OSC A: sine, LEVEL 55%. OSC B: sine, OCT +1, SEM +7, FIN +4 cents, LEVEL 0%, power on. A WARP → FM (B), start 20%. Polyphony 8+.',movement:'ENV 3: ATK 0, HOLD 0, DEC 550 ms, SUS minimum, REL 150 ms. Assign upward to A Warp so the strike rises from 20% to about 35%.',fx:'Reverb MIX 18%, DECAY 2.5 s. Let the dry bell ring before adding delay.',why:'The almost-3:1 modulator ratio creates a bell-like harmonic pattern with a slight beating edge.',hear:'A pitched strike that keeps ringing. It should not need huge reverb to sound bell-like.',fix:'Too clangy for the chord: remove B FIN offset and reduce Warp. Too sharp: lower cutoff to 5000 Hz.',variants:['B SEM 0, OCT +1: rounder exact 2:1 tone.','ENV 1 DEC 350 ms: a short bell pluck.']});
patch('afro-mallet','Wooden afro-house mallet','Leads',2,'Afro house · organic house','A dry wooden knock with just enough pitch to carry a hook.',{wave:'sine',fm:.7,ratio:4,note:60,pattern:'syncopated',amp:[1,0,320,0,75],cut:3300,peak:3300,env:0,source:'A: sine LEVEL 60%. B: sine OCT +2, LEVEL 0%, power on. A WARP FM (B), base 3%. Polyphony 8.',movement:'ENV 3: ATK 0, HOLD 0, DEC 55 ms, SUS minimum, REL 20 ms. Assign upward to A Warp so its attack reaches about 25%.',fx:'Reverb MIX 10%, DECAY 0.9 s. Optional Delay dotted 1/8, FEEDBACK 18%, MIX 12%.',why:'A very fast burst of modulation supplies the wooden hit; the simple body keeps the pitch clear.',hear:'A “tok” at the front with a brief rounded ring.',fix:'Sounds like a long bell: shorten ENV 3 first, then ENV 1. Too dull: raise the modulation peak a little.',variants:['B OCT +1: softer, rounder wood.','ENV 3 DEC 100 ms: more metallic, less woody.']});
patch('sync-lead','Tearing sync lead','Leads',2,'Peak-time techno · electro house','A bright, tearing edge that moves without changing the played note.',{note:57,pattern:'melody',amp:[3,0,450,50,100],cut:1700,peak:6000,env:250,source:'OSC A: Basic Shapes → saw, LEVEL 45%, UNISON 1. A WARP → Sync, amount about 15%. Leave OSC B off.',movement:'ENV 3: ATK 0, HOLD 0, DEC 240 ms, SUS minimum, REL 80 ms. Assign upward to A Warp, from about 15% to 40%. The waveform resets faster internally; keep OSC pitch unchanged.',fx:'Distortion Soft Clip, DRIVE 15%, MIX 20%. Delay straight 1/8, feedback 18%, MIX 15%.',why:'Sync changes the harmonic pattern by forcing extra waveform resets. The fundamental can stay anchored while the tone rips upward.',hear:'A bright “yaa” with a fixed musical pitch underneath.',fix:'Too thin or sharp: reduce Sync amount and cutoff peak. Verify you moved Warp, not oscillator semitone.',variants:['ENV 3 ATK 100 ms: a rising bite.','Hold Warp still and modulate only cutoff: simpler, steadier lead.']});
patch('wavetable-seq','Wavetable sequence','Leads',2,'Hypnotic · melodic techno','A sequence whose source shape changes slowly across repeated notes.',{note:57,pattern:'hypnotic',amp:[3,0,260,0,60],cut:1300,peak:4200,env:140,source:'OSC A: choose any factory wavetable with visibly different neighbouring frames. UNISON 1, LEVEL 50%. Find a pleasant starting frame with WT POS before adding movement. Avoid scanning Basic Shapes between unrelated shapes for this first exercise.',movement:'LFO 1: triangle, BPM on, RATE 2 bars, FREE. Assign unipolar to WT POS across only 15–25% of the table. Keep Warp off to hear the table itself.',why:'The oscillator changes its harmonic recipe before it reaches the filter. A narrow scan often feels more coherent than sweeping the whole table.',hear:'The same notes slowly change colour; their loudness should not jump dramatically.',fix:'Jumps or harsh frames: reduce the scan range and choose a smoother part of the table. Each table is different, so no WT POS number works universally.',variants:['RETRIG on: every note begins at the same timbre.','ENV 3 rather than LFO: a bright frame on attack, softer frame in the tail.']});

patch('warm-pad','Warm analogue pad','Pads',1,'Deep house · ambient techno','A slowly opening chord bed with a soft edge.',{note:57,pattern:'pad',amp:[700,0,1800,70,1800],cut:1200,peak:3200,env:1800,envAttack:900,envSustain:50,envRelease:1500,voices:4,detune:8,source:'OSC A: saw, LEVEL 35%, UNISON 4, DETUNE 0.08. MONO off, polyphony at least 12. Play a chord and hold it for two bars.',movement:'ENV 2: ATK 900 ms, HOLD 0, DEC 1800 ms, SUS 50%, REL 1500 ms. Open cutoff from 1200 to about 3200 Hz. Let the chord develop before judging it.',fx:'Reverb MIX 20%, DECAY 3 s. If the source already feels wide, leave chorus off.',why:'Slow amplitude and filter attacks hide the transient. Long release connects chord changes, but also adds overlapping voices.',hear:'A gradual bloom with no obvious click; the chord is still intelligible when the reverb is bypassed.',fix:'First chord seems silent: hold it for two seconds. Chord changes turn muddy: shorten REL and use closer voicings.',variants:['Triangle instead of saw: gentler bed.','ATK 100 ms, REL 600 ms: more rhythmic chord swells.'],mix:'Keep the pad quieter than you think when the hook enters. Remove low chord notes before using a steep high-pass filter.'});
patch('string-pad','Airy string machine','Pads',2,'Classic house · Detroit','A lightly detuned, sustained ensemble with a clear upper register.',{note:60,pattern:'pad',amp:[280,0,1000,85,1000],cut:4500,peak:4500,env:0,voices:6,detune:9,source:'OSC A: saw, UNISON 6, DETUNE 0.10, LEVEL 35%. MONO off, polyphony 16. Keep chords around MIDI 60–79.',fx:'Chorus MIX 20%, slow RATE around 0.3 Hz and moderate depth. Reverb MIX 15%, DECAY 2.5 s.',movement:'LFO 1 sine, Hz mode 0.2 Hz, FREE; assign a very small bipolar amount to A FIN, about ±3 cents. This is slow vibrato, not a pitch-bend effect.',why:'Unison makes an ensemble; a little chorus and pitch drift soften the static digital edge.',hear:'A smooth, sustained string-like layer. This is a synth ensemble, not a realistic bowed-string multisample.',fix:'Out of tune: remove FIN modulation before changing the chord. Washed out: reduce chorus mix.',variants:['UNISON 3: leaner and more intimate.','ATK 20 ms and DEC 400 ms, SUS 0%: string stab.']});
patch('breathing-pad','Breathing rhythm pad','Pads',2,'Progressive house · melodic techno','A held chord that opens in time with the track.',{note:57,pattern:'pad',amp:[150,0,800,100,500],cut:600,peak:600,env:0,voices:3,detune:6,wobble:1,source:'OSC A: saw, UNISON 3, DETUNE 0.07, LEVEL 40%. Polyphony 12+. Hold a chord for two bars.',movement:'LFO 1: draw a smooth rise and fall, BPM on, RATE 1/4, RETRIG. Route unipolar to Filter 1 Cutoff: 600 → 4000 Hz. Start every chord on a beat. For transport-aligned motion across notes, explore HOST synchronization after this works.',fx:'Reverb MIX 15%, DECAY 2 s, after the movement. It will soften the gaps.',why:'Periodic brightness makes a held chord pulse without retriggering its amplitude envelope.',hear:'A chord breathing once per beat. This does not react to the actual kick signal.',fix:'Pulse restarts awkwardly: align note starts or use a host-synced LFO. For real kick ducking, use a DAW sidechain compressor.',variants:['Rate 1/8: quicker movement.','Assign the LFO to level instead for a more pronounced gate; use smooth edges to avoid clicks.']});
patch('grain-cloud','Granular voice cloud','Pads',3,'Ambient techno · organic house','Turn one recorded vowel into a slow, drifting atmosphere.',{engine:'Granular',note:60,pattern:'pad',amp:[900,0,1500,80,2200],cut:5500,peak:5500,env:0,source:'Record a steady 2–4 second “ah” yourself in the DAW. Export WAV. OSC A header → Granular, then load your WAV into the sample display. UNISON 1, LEVEL 45%. Start with one held note at the sample’s root pitch; establish that pitch with your DAW tuner.',movement:'Open the granular parameters. Start with grains around 80–150 ms and enough overlapping grains for a continuous tone. Move the playback position into the steady vowel, away from the breath. Add only a small random position spread, then slowly modulate position over two bars. Parameter scales vary; use the tooltip and overlap by ear.',fx:'Reverb MIX 20%, DECAY 3.5 s. Add this only after the dry grains join smoothly.',why:'Overlapping fragments stretch a moment into a texture. Source quality and position matter more than filling every modulation slot.',hear:'A sustained vowel cloud rather than intelligible speech. Your recording determines the result.',fix:'Tiny machine-gun chatter: lengthen grains and increase overlap. Blurry consonants: move deeper into the vowel.',variants:['Record a bowed or scraped household object for an unpitched texture.','Use shorter grains for a rougher digital surface.'],macro:['Travel','Sample playback position: limit movement to the steady portion of your recording.'],mix:'Keep the dry cloud audible while designing. Save your own source alongside the patch and embed it before moving the preset.'});
patch('spectral-freeze','Spectral frozen chord','Pads',3,'Dub techno · cinematic techno','Suspend a moment from your own chord recording and play its harmonics.',{engine:'Spectral',note:60,pattern:'drone',amp:[600,0,1800,90,2000],cut:7000,peak:7000,env:0,source:'Render a sustained chord you made with Deep house stab, with no delay or reverb. OSC A header → Spectral; load the WAV. UNISON 1, LEVEL 40%. The file already contains a chord: play one MIDI note at its untransposed root.',movement:'Find a stable point after the attack. Start SCAN at 0% to hold that point; increase to 5–15% for a very slow evolution. Leave scan Key Track off so different played pitches do not change the scan speed.',fx:'Reverb MIX 15%, DECAY 3 s. Avoid masking the spectral source with a huge wet signal.',why:'Spectral resynthesis lets time move very slowly while you still play pitched material.',hear:'A suspended, slightly otherworldly version of your source chord. The source harmony remains baked in.',fix:'Silence at zero scan: move the start away from a silent region. Wrong harmony: remember that transposing a recorded chord moves every note together.',variants:['Negative SCAN: unfold the source backward.','Record one note instead of a chord for a texture you can play polyphonically.'],macro:['Time','SCAN: 0% → 25%; stay near zero for a suspended sound.']});
patch('choir-pad','Distant choir','Pads',1,'Melodic techno · deep house','A human harmonic layer from Serum 2’s factory multisamples.',{engine:'Multisample',note:60,pattern:'pad',amp:[450,0,1800,75,1300],cut:3500,peak:3500,env:0,source:'OSC A header → Multisample → Factory → Choir. Audition a sustained vowel, UNISON 1, LEVEL 40%. MONO off, polyphony 12+. Play a three-note chord in the middle register.',fx:'Reverb MIX 22%, DECAY 3 s. If the words or breath are too prominent, choose a different source before adding more effects.',movement:'Macro 1 opens cutoff from 1800 → 6000 Hz. Keep pitch modulation off initially; recorded voices already have motion.',why:'The recording supplies vocal resonances and natural variation. A soft envelope turns it into a supporting layer.',hear:'A recognisably human bed behind the lead, without an exaggerated new attack on every note.',fix:'Muffled rather than distant: open cutoff and lower level. Chords cut out: raise polyphony or shorten release.',variants:['ATK 15 ms, DEC 350 ms, SUS 0%: a choral stab.','Single-note line in a lower register: a dark vocal drone.']});

patch('short-kick','Short synth kick','Drums',2,'House · minimal techno','A sine-wave thump with a fast drop into a stable body.',{wave:'sine',note:33,pattern:'kick',amp:[1,0,220,0,35],filter:'Off',cut:18000,peak:18000,pitchDrop:24,pitchTime:.03,source:'OSC A: sine, LEVEL 60%, UNISON 1, RAND 0%. Use PHASE 0° as a starting point and listen for a clean start. Play MIDI 33 (55 Hz at OCT 0); no oscillator transpose.',movement:'ENV 2: ATK 0 ms, HOLD 0, DEC 30 ms, SUS minimum, REL 15 ms. Route to A CRS (coarse pitch) or the oscillator pitch destination in Matrix: unipolar +24 semitones at the peak, returning to the played note. Use tooltip pitch units to set the range.',why:'The rapidly falling pitch supplies the punch. A separate, slower volume decay supplies the body.',hear:'A quick knock settling into a low thump, not a long laser swoop.',fix:'Laser: shorten pitch decay to 15 ms. Click: increase amp ATK to 2–3 ms. Weak body: lower pitch depth before turning up the level.',macro:['Body','ENV 1 DEC: 140 → 350 ms.'],variants:['Pitch depth +12 semitones: rounder house kick.','Pitch decay 45 ms: more obvious electronic knock.'],mix:'Tune the settled body by ear with the track; the fast attack has no single stable pitch. Use one kick voice and leave room for the bass.'});
patch('warehouse-kick','Driven warehouse kick','Drums',2,'Raw techno · hard techno','A longer kick body with a controlled distorted edge.',{wave:'sine',note:31,pattern:'kick',amp:[1,0,420,0,45],filter:'Off',cut:18000,peak:18000,pitchDrop:30,pitchTime:.045,drive:.45,source:'OSC A: sine, LEVEL 45%, UNISON 1, RAND 0%. Play MIDI 31 (about 49 Hz). Leave SUB and NOISE off initially.',movement:'ENV 2: ATK 0, HOLD 0, DEC 45 ms, SUS minimum, REL 15 ms. Assign to A coarse pitch for a +30 semitone attack returning to the played pitch. Keep the movement unipolar.',fx:'Distortion Soft Clip, DRIVE 35%, MIX 50%. Match the output to bypass. Reduce distortion if the low body collapses into a buzz.',why:'A longer pitch fall and clipped body create aggression. Distortion changes the envelope as well as the tone.',hear:'A defined strike followed by a rough low body that dies before the next kick.',fix:'Tail eats the groove: shorten ENV 1 decay. Thin and loud: reduce drive and listen at matched level.',variants:['Pitch decay 20 ms: faster and more focused.','Play two semitones higher: a tighter, more mid-forward kick.'],mix:'At 140 BPM, quarter notes are about 429 ms apart. A 420 ms decay plus release can be too long; shorten by ear with bass playing.'});
patch('closed-hat','Tight closed hat','Drums',1,'House · techno · minimal','A short filtered burst of noise that marks the subdivisions.',{wave:'noise',note:60,pattern:'hat',amp:[1,0,45,0,12],filter:'High 12',cut:6500,peak:6500,env:0,source:'Turn OSC A off. Enable NOISE and choose a steady white-noise-like factory noise by auditioning. LEVEL 35%. Route NOISE to Filter 1; choose High 12 (high-pass). Leave one-shot playback off for a continuous noise source shaped by ENV 1.',why:'Noise supplies a broad spectrum. A high-pass filter removes the low body; a short amplitude envelope makes a hat.',hear:'A crisp “ts” without a low thud.',fix:'Only a click: increase DEC to 65 ms. Too sandy: lower cutoff to 4500 Hz and reduce level.',movement:'Write eighth or sixteenth notes. Assign VELO → Noise LEVEL a small positive amount, then alternate velocities 90 and 55. Confirm quieter notes are actually quieter.',macro:['Tight','ENV 1 DEC: 25 → 100 ms.'],variants:['DEC 90 ms: looser hat.','High-pass 9000 Hz: thinner air layer; may disappear on some speakers.'],mix:'Set the hat level with the whole groove playing. A bright hat can feel much louder than its meter suggests.'});
patch('open-hat','Offbeat open hat','Drums',1,'House · disco · techno','The longer splash between the kick beats.',{wave:'noise',note:60,pattern:'offbeat',amp:[2,0,330,0,40],filter:'High 12',cut:5200,peak:5200,env:0,source:'OSC A off. NOISE on: use a steady bright noise. LEVEL 30%, route to Filter 1, High 12. MONO on so the next note can interrupt the previous voice.',movement:'Place one short note on each offbeat. First use notes long enough to hear the 330 ms decay. Then shorten gates to fit the groove. For open/closed-hat choke across two separate patches, use a DAW drum rack choke group.',why:'The source can be identical to a closed hat. The longer decay and placement create a different role.',hear:'A splash that falls away before the next kick, with some room around it.',fix:'Uncontrolled overlap: check note gates and MONO; a separate closed-hat track will not automatically choke this instance.',macro:['Open','ENV 1 DEC: 150 → 500 ms.'],variants:['DEC 180 ms: short open-hat shuffle.','ATK 10 ms: softer shaker-like splash.']});
patch('clap','Synthetic handclap','Drums',2,'House · raw techno','A cluster of three little bursts followed by a noisy tail.',{wave:'noise',note:60,pattern:'clap',amp:[1,0,260,100,45],filter:'Band 12',cut:1700,peak:1700,res:20,env:0,clap:true,source:'OSC A off. NOISE on, steady white-noise-like source, route Filter 1. Filter type Band 12, cutoff 1700 Hz, RES 20%. Set Noise LEVEL to 0% before the next modulation assignment.',movement:'LFO 1 in ENVELOPE mode, BPM off; make its full cycle about 250 ms (roughly 4 Hz). Draw three short peaks near 0, 15 and 30 ms, then a declining tail reaching zero at 220 ms. Give every peak a small ramp. Assign upward to Noise LEVEL, 0 → 50%. Hold the MIDI note about 300 ms so ENV 1 does not cut off the cluster.',why:'Several close attacks suggest hands arriving slightly apart. A single envelope burst sounds more like a snare.',hear:'“P-p-pah” packed into one clap, followed by a small tail.',fix:'A repeating clap machine: choose ENVELOPE, not looping LFO mode. No sound: check modulation depth from the zero base level.',fx:'Reverb MIX 10%, DECAY 0.7 s after the dry clap is convincing.',macro:['Room','Reverb MIX: 0% → 20%.'],variants:['Bring peaks closer: tighter electronic clap.','Band-pass at 2400 Hz: lighter, more cutting clap.']});
patch('snare','Body-and-noise snare','Drums',2,'Techno · electro · house','A pitched knock plus a short noise tail, independently shaped.',{wave:'snare',note:55,pattern:'clap',amp:[1,0,240,0,30],filter:'High 12',cut:1100,peak:1100,env:0,source:'OSC A: triangle, LEVEL 30%, route Main (bypasses Filter 1). Play MIDI 55, about 196 Hz. NOISE: steady bright source, LEVEL 0%, route Filter 1 High 12 at 1100 Hz. UNISON 1.',movement:'ENV 2 ATK 0, HOLD 0, DEC 160 ms, SUS minimum, REL 20 ms → Noise LEVEL, upward 0 → 45%. A gets ENV 1; noise gets ENV 2 multiplied by the normal amp envelope. No filter-envelope assignment here.',why:'The triangle supplies the drum body and the noise suggests the snare wires. Separate routing prevents the high-pass filter from removing the body.',hear:'A definite mid-low knock followed by “shh”.',fix:'Thin: verify A routes Main, not the noise high-pass filter. Too tonal: shorten A’s amp decay or lower A LEVEL.',variants:['A sine: smoother body.','Noise ENV 2 DEC 90 ms: tight, dry snare.'],macro:['Snap','Noise ENV 2 modulation depth: 20% → 55%.']});
patch('shaker','Soft shaker','Drums',1,'Organic house · afro house · microhouse','A soft noise gesture whose accents create the hand movement.',{wave:'noise',note:60,pattern:'shaker',amp:[12,0,65,0,20],filter:'High 12',cut:3800,peak:3800,env:0,source:'OSC A off. NOISE on: choose continuous bright noise, LEVEL 25%, route Filter 1 High 12. RES 0%.',res:0,movement:'Use sixteenth notes. Add a small VELO → Noise LEVEL route; alternate 45, 75, 55, 95 velocities. Apply a little DAW swing to the second sixteenth of each pair after the straight pattern works.',why:'A little attack time removes the hard electronic tick. Velocity and timing make the friction feel performed.',hear:'“Sha-ka” gestures rather than identical machine ticks.',fix:'Sounds like a hat: increase ATK to 18 ms and lower filter cutoff to 3000 Hz. Too smeared: shorten DEC.',variants:['ATK 3 ms: sharper grain.','Remove every fourth hit: more air and forward motion.'],macro:['Grain','ENV 1 ATK: 3 → 22 ms.']});
patch('tom','Tuned tom / conga','Drums',2,'Tribal techno · afro house','A brief falling pitch and rounded resonant body.',{wave:'sine',note:45,pattern:'syncopated',amp:[1,0,260,0,40],filter:'Off',cut:18000,peak:18000,pitchDrop:7,pitchTime:.025,source:'OSC A: sine, LEVEL 60%, UNISON 1, RAND 0%. Start at MIDI 45 (110 Hz). Leave FX off.',movement:'ENV 2: ATK 0, HOLD 0, DEC 25 ms, SUS minimum, REL 10 ms. Assign to A coarse pitch, unipolar +7 semitones at the start, returning to the MIDI pitch.',why:'A modest pitch drop feels like a drum skin relaxing; a huge pitch drop sounds more like a kick or laser.',hear:'A rounded “dum” with a clearly tunable body.',fix:'Kick-like: raise MIDI by an octave and shorten DEC. Too laser-like: reduce pitch modulation to +3 semitones.',macro:['Skin','ENV 1 DEC: 100 → 450 ms.'],variants:['Triangle source: a woody conga-like edge.','Pitch depth +3, DEC 140 ms: tight high tom.']});
patch('metal-perc','Metallic FM percussion','Drums',2,'Industrial · hardgroove · minimal','An inharmonic hit that cuts through without becoming a lead.',{wave:'sine',fm:3,ratio:2.61,note:57,pattern:'syncopated',amp:[1,0,180,0,45],filter:'High 12',cut:700,peak:700,env:0,source:'A: sine LEVEL 50%. B: sine, OCT +1, SEM +5, FIN +35 cents, LEVEL 0%, power on. A WARP → FM (B), amount about 35%. Route A through Filter 1 High 12.',movement:'ENV 3: ATK 0, HOLD 0, DEC 90 ms, SUS minimum, REL 25 ms. Assign upward to Warp, base 15% and peak about 40%.',why:'A non-integer frequency ratio produces partials that do not line up as a simple musical harmonic series.',hear:'A small metal “kling”, with a shorter tail than the FM bell.',fix:'Too much pitch: alter B FIN or SEM slightly. Too piercing: lower Warp amount and output before EQ.',variants:['DEC 70 ms: tiny metal tick.','DEC 500 ms: resonant bowl; use fewer notes.'],macro:['Metal','A FM (B) amount: 10% → 40%.']});
patch('rim','Rim / clave tick','Drums',1,'Minimal · house · hardgroove','A tiny tuned knock that stays out of the low end.',{wave:'triangle',note:81,pattern:'clave',amp:[1,0,35,0,12],filter:'Band 12',cut:2100,peak:2100,env:0,res:15,source:'OSC A: triangle, LEVEL 55%, UNISON 1. Play MIDI 81 (880 Hz). Filter 1 Band 12 at 2100 Hz, RES 15%.',movement:'Start with a sparse pattern: hits on sixteenth steps 1, 7 and 12. Add a quieter pickup near the end of every second bar. No LFO required.',why:'A high pitch and very short body create a wooden tick. Where you place it gives the pattern its identity.',hear:'A dry “tok” with a little tone, not a wide noise burst.',fix:'Just a click: DEC 50–70 ms. Too thin: bypass the band-pass and lower A LEVEL.',variants:['Square source: harder rim edge.','MIDI 74: lower, woodier clave.'],macro:['Knock','ENV 1 DEC: 20 → 85 ms.']});

patch('noise-rise','Noise riser','FX',1,'House · techno · transitions','A controlled opening of brightness over four bars.',{wave:'noise',note:60,pattern:'rise',amp:[30,0,500,100,150],filter:'MG Low 12',cut:300,peak:300,env:0,source:'OSC A off. NOISE on: steady white-noise-like source, LEVEL 25%, route Filter 1. RES 10%.',res:10,movement:'Assign Macro 1 to Filter 1 Cutoff: base 300 Hz → top 12000 Hz. In your DAW, hold one note for four bars and draw Macro 1 automation rising from minimum to maximum. Put the end exactly on the next section; release the note there.',fx:'Reverb MIX 15%, DECAY 1.5 s. Shorten or automate the tail if you want a clean drop.',why:'An opening filter reveals more high-frequency energy. The automation duration makes it a transition.',hear:'A smooth growth from low hush to bright rush, with no repeated restart.',fix:'Abrupt start: increase ENV 1 attack. Rise feels too loud at the top: reduce Noise LEVEL or draw compensating level automation.',macro:['Rise','Filter 1 Cutoff: 300 → 12000 Hz.'],variants:['Automate a high-pass upward as well: a thinner final sweep.','Use two bars for a short fill instead of four.'],mix:'Finish the rise where the next section begins. A quieter final beat or an intentional gap can make the drop clearer than a louder riser.'});
patch('downlifter','Noise downlifter','FX',1,'House · techno · transitions','A short bright wash that darkens behind the first beat of a new section.',{wave:'noise',note:60,pattern:'impact',amp:[3,0,1900,0,150],filter:'MG Low 12',cut:400,peak:11000,env:1500,source:'OSC A off. NOISE on: continuous bright noise, LEVEL 25%, route Filter 1.',fx:'Reverb MIX 18%, DECAY 2 s. Keep the wet signal below the new section’s main percussion.',movement:'ENV 2 ATK 0, HOLD 0, DEC 1500 ms, SUS minimum, REL 100 ms. Assign upward to Filter 1 Cutoff: 400 → 11000 Hz at the start, falling back to 400. Hold the MIDI trigger two seconds to hear the decay.',why:'A descending brightness curve releases tension while the amplitude falls away.',hear:'An initial “shhh” moving backward into the track, not a new rising build.',fix:'It swells instead of falls: check ENV 2 attack and modulation polarity. Cutoff base should be dark, with the envelope opening it.',variants:['Both decays 700 ms: compact fill.','Cutoff peak 4000 Hz: dark, low-key transition.']});
patch('impact','Cinematic low impact','FX',2,'Melodic techno · warehouse','A falling low tone under a short noise burst and a larger room.',{wave:'sine',note:33,pattern:'impact',amp:[2,0,1500,0,200],filter:'MG Low 12',cut:4500,peak:4500,env:0,pitchDrop:19,pitchTime:.12,source:'OSC A: sine LEVEL 50%, UNISON 1. NOISE on, LEVEL 0%, route Filter 1. A routes Main. MIDI 33 is the settled low pitch.',movement:'ENV 2: ATK 0, HOLD 0, DEC 120 ms, SUS minimum, REL 30 ms → A coarse pitch, +19 semitones downward to the played note. ENV 3: ATK 0, HOLD 0, DEC 300 ms, SUS minimum, REL 80 ms → Noise LEVEL, upward 0 → 25%.',fx:'Reverb MIX 22%, DECAY 3 s. If the low end blurs, send a high-passed copy to reverb in your DAW and reduce Serum’s wet mix.',why:'The pitched fall conveys weight, noise supplies the strike, and the room makes the event feel larger.',hear:'One impact with a low body and fading air, rather than a continuous bass note.',fix:'Low end swamps the next bar: shorten ENV 1 DEC and reduce wet mix. Noise masks the transient: shorten ENV 3.',variants:['MIDI +12 semitones: smaller, tighter impact.','Remove noise: pure sub drop.'],macro:['Scale','Reverb MIX: 5% → 30%.']});
patch('laser','Pitch laser / zap','FX',2,'Electro · minimal · techno','A quick pitch sweep for fills, punctuation and playful percussion.',{wave:'sine',note:60,pattern:'zap',amp:[1,0,180,0,30],filter:'Off',cut:18000,peak:18000,pitchDrop:36,pitchTime:.1,source:'OSC A: sine LEVEL 50%, UNISON 1. Play MIDI 60. Keep other sources off.',movement:'ENV 2: ATK 0, HOLD 0, DEC 100 ms, SUS minimum, REL 20 ms. Assign unipolar to A coarse pitch: +36 semitones at the start, returning to the played note. Verify the destination range in semitones.',why:'A large, audible pitch fall is the effect itself. This is the same principle as a kick, with a higher base and a longer sweep.',hear:'A definite downward “pew”.',fix:'Only a click: lengthen pitch decay. Wrong direction: use positive depth from a low base, not negative depth.',variants:['Pitch depth +12, DEC 40 ms: small zap percussion.','ENV 2 ATK 150 ms, DEC 0, SUS maximum: rising science-fiction chirp.'],macro:['Fall','ENV 2 DEC: 30 → 300 ms.']});
patch('vocal-chop','Your own vocal chop','FX',2,'Vocal house · stutter house','Turn a short recorded syllable into a playable, tightly gated hook.',{engine:'Sample',note:60,pattern:'melody',amp:[3,0,400,100,35],filter:'MG Low 12',cut:8000,peak:8000,env:0,source:'Record a steady pitched “ah” or “hey”, export WAV, and trim extra silence. OSC A header → Sample; load the file. LEVEL 50%, UNISON 1; loop off. Find the original pitch with a tuner and set the sample’s root note accordingly so MIDI transposes it predictably.',movement:'Select a clean syllable with sample start/end points. Use short MIDI gates with ENV 1 release 35 ms. Choose playback that responds to note length (not a tails/one-shot mode that deliberately runs on). Audition one note before writing a melody.',fx:'Delay straight 1/8, FEEDBACK 20%, MIX 15%. Keep reverb MIX under 12% so consonants stay clear.',why:'A recognizable attack and a controllable gate let a recorded voice act like an instrument.',hear:'A clean, repeatable syllable on each note, without a click at the crop point.',fix:'Wrong pitch: check root mapping with a tuner. Clicks: adjust start to a quiet crossing and raise ATK/REL slightly. Sample still plays on: check playback mode.',variants:['Use just the vowel for a smoother melodic chop.','Move the start later for a short rhythmic consonant hit.'],macro:['Shade','Filter 1 Cutoff: 1800 → 10000 Hz.'],mix:'Write the rhythm dry. Leave space for a lead vocal if the track already has one. Embed your own sample when saving.'});
patch('rumble','Resampled techno rumble','FX',3,'Warehouse · deep techno','Build the rumble as an audio texture, then make it leave room for the kick.',{engine:'Sample',note:33,pattern:'rumble',amp:[8,0,900,85,90],filter:'MG Low 24',cut:180,peak:180,env:0,source:'First make the Short synth kick. In the DAW, record one hit through 100% wet reverb with about 2 s decay. Render that wet tail to WAV. In a new Init patch choose OSC A → Sample and load the tail; LEVEL 40%, UNISON 1, loop off. Play its untransposed root initially.',movement:'Set sample start just after the original transient so the rumble does not become another kick. Draw repeating MIDI notes aligned to your groove. In the DAW put a compressor after Serum, enable external sidechain from the dry kick, and lower threshold until each kick visibly ducks the tail. Start attack 1–5 ms, release 100–200 ms, then tune to tempo.',fx:'Optional gentle distortion before a low-pass in the DAW, or Serum FX if routed appropriately. The recipe filter at 180 Hz trims the noisy reverb tail. No additional reverb needed.',why:'Reverb provides a dense tail; filtering isolates the low texture; kick-triggered ducking creates the pumping space.',hear:'Low movement between the kicks, with a clearly audible dip whenever the dry kick hits.',fix:'A constant swamp: shorten the source, lower the rumble level, then increase ducking. Tuning sounds wrong: transpose the rendered tail by ear; it is not a pure sine with one exact pitch.',variants:['Render a shorter room for a tighter rumble.','High-pass the source gently before the final low-pass to reduce unusable sub energy.'],macro:['Weight','Filter 1 Cutoff: 100 → 280 Hz.'],mix:'The browser does not model this rendered chain. Judge it in your DAW with the dry kick. Save the source WAV and embed your custom sample.'});
